package com.example.smartpantry;
import android.app.*;import android.content.*;import android.database.*;import android.widget.*;
public class EditIngredientActivity extends Activity{
 int id=-1;EditText name,qty,expiry;Spinner unit;String[] units={"piece","g","kg","ml","l","slice","clove","tbsp","tsp"};
 public void onCreate(android.os.Bundle b){super.onCreate(b);id=getIntent().getIntExtra("id",-1);LinearLayout l=UI.page(this,id<0?"Add Ingredient":"Edit Ingredient");name=UI.input(this,l,"Ingredient name (e.g. tomatoes)");qty=UI.input(this,l,"Quantity (e.g. 2)");qty.setInputType(8194);unit=new Spinner(this);unit.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,units));l.addView(unit);expiry=UI.input(this,l,"Expiry date YYYY-MM-DD (optional)");if(id>=0){DB db=new DB(this);Cursor c=db.getReadableDatabase().rawQuery("SELECT name,quantity,unit,expiry FROM pantry WHERE id=?",new String[]{""+id});if(c.moveToFirst()){name.setText(c.getString(0));qty.setText(""+c.getDouble(1));for(int i=0;i<units.length;i++)if(units[i].equals(c.getString(2)))unit.setSelection(i);expiry.setText(c.getString(3));}c.close();db.close();}UI.button(this,l,"Save Ingredient",()->save());if(id>=0)UI.button(this,l,"Delete Ingredient",()->new AlertDialog.Builder(this).setMessage("Delete this ingredient?").setPositiveButton("Delete",(d,w)->{DB db=new DB(this);db.getWritableDatabase().delete("pantry","id=?",new String[]{""+id});db.close();finish();}).setNegativeButton("Cancel",null).show());}
 void save(){String n=name.getText().toString().trim(),q=qty.getText().toString().trim(),e=expiry.getText().toString().trim();if(n.isEmpty()){name.setError("Name required");return;}double amount;try{amount=Double.parseDouble(q);if(!Double.isFinite(amount)||amount<=0)throw new Exception();}catch(Exception ex){qty.setError("Enter a positive number");return;}if(!e.isEmpty()&&!e.matches("\\d{4}-\\d{2}-\\d{2}")){expiry.setError("Use YYYY-MM-DD");return;}if(!e.isEmpty()){try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US);f.setLenient(false);f.parse(e);}catch(Exception ex){expiry.setError("Invalid date");return;}}DB db=new DB(this);ContentValues v=new ContentValues();v.put("name",n);v.put("quantity",amount);v.put("unit",units[unit.getSelectedItemPosition()]);v.put("expiry",e);if(id<0)db.getWritableDatabase().insert("pantry",null,v);else db.getWritableDatabase().update("pantry",v,"id=?",new String[]{""+id});db.close();finish();}
}
